def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after '+')
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split pre-release (everything after '-' in the core version)
        if '-' in v_without_build:
            parts = v_without_build.split('-', 1)
            version_part = parts[0]
            prerelease = parts[1]
        else:
            version_part = v_without_build
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        version_nums = tuple(map(int, version_part.split('.')))

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
            parsed_prerelease = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    parsed_prerelease.append((0, int(identifier)))
                else:
                    parsed_prerelease.append((1, identifier))
            prerelease_tuple = tuple(parsed_prerelease)
        else:
            prerelease_tuple = None

        return version_nums, prerelease_tuple

    def compare_key(v):
        version_nums, prerelease_tuple = parse_version(v)

        # For sorting: version numbers first, then pre-release status
        # If prerelease_tuple is None, it sorts after (has pre-release)
        # We use (version_nums, prerelease_tuple or float('inf'), ...)

        if prerelease_tuple is None:
            # No pre-release: sorts after the same version with pre-release
            # Use a tuple that sorts after any pre-release tuple
            return (version_nums, (float('inf'),))
        else:
            # Has pre-release: sorts before the same version without pre-release
            return (version_nums, prerelease_tuple)

    return sorted(versions, key=compare_key)

